package com.bank.config;

import java.util.*;
import java.util.logging.Logger;

// Models a ConfigMap: non-sensitive key/value settings that can be edited live.
public class ConfigMapStore {
    private static final Logger log = Logger.getLogger(ConfigMapStore.class.getName());
    private final Map<String, String> data = new HashMap<>();

    public ConfigMapStore(String version) { data.put("version", version); }
    public void put(String k, String v) { data.put(k, v); log.info(() -> "ConfigMap edited: " + k + "=" + v + " (disk only!)"); }
    public String get(String k) { return data.get(k); }
}
