package com.bank.config;

import java.util.*;
import java.util.logging.Logger;

// Models a Secret: sensitive values, base64 at rest, RBAC-restricted.
public class SecretStore {
    private static final Logger log = Logger.getLogger(SecretStore.class.getName());
    private final Map<String, String> data = new HashMap<>();

    public void rotate(String key, String newValue) {
        data.put(key, newValue);
        log.warning(() -> "Secret rotated: " + key + "=**** (running pods still cache the OLD value)");
    }
    public String get(String k) { return data.get(k); }
}
