package com.bank.config;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Reads config as ENV at startup (snapshot) and caches the DB password too.
// This is why a live ConfigMap/Secret edit does NOT change behaviour.
public class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());

    private final BigDecimal transferFee;   // snapshot at construction (env-style)
    private final String dbPassword;        // cached credential

    public PaymentService(ConfigMapStore cfg, SecretStore sec) {
        this.transferFee = new BigDecimal(cfg.get("transfer.fee"));  // read ONCE
        this.dbPassword = sec.get("db.password");                   // cached ONCE
        log.info(() -> "PaymentService started: fee=" + transferFee + " (frozen at startup)");
    }

    public void transfer(Account from, Account to, BigDecimal amount) {
        BigDecimal total = amount.add(transferFee);
        from.debit(total); to.credit(amount);
        log.info(() -> "transfer " + from.getAccountId() + "->" + to.getAccountId()
                + " amount Rs." + amount + " fee Rs." + transferFee + " (using CACHED fee)");
    }
    public BigDecimal getTransferFee() { return transferFee; }
}
