package com.bank.config;

import java.util.logging.Logger;

// Simulates Stakater Reloader / kubectl rollout restart: recreate the service
// so it re-reads config at startup. This is how a change actually takes effect.
public class Reloader {
    private static final Logger log = Logger.getLogger(Reloader.class.getName());

    public PaymentService rolloutRestart(ConfigMapStore cfg, SecretStore sec) {
        log.info("rollout restart triggered -> new Pod re-reads ConfigMap + Secret");
        return new PaymentService(cfg, sec);
    }
}
