package com.bank.config;

import java.math.BigDecimal;
import java.util.logging.*;

public class ConfigReloadDemo {
    private static final Logger log = Logger.getLogger(ConfigReloadDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        ConfigMapStore cfg = new ConfigMapStore("v7");
        cfg.put("transfer.fee", "20");
        SecretStore sec = new SecretStore();
        sec.rotate("db.password", "oldPass123");

        PaymentService svc = new PaymentService(cfg, sec);
        svc.transfer(rajesh, priya, new BigDecimal("50000"));   // fee 20

        // Operator edits the ConfigMap live -> fee should become 35
        cfg.put("transfer.fee", "35");
        svc.transfer(rajesh, priya, new BigDecimal("50000"));   // STILL fee 20 (snapshot!)
        log.warning("fee change NOT applied — env-style value frozen at startup");

        // Apply the change properly via a rollout restart
        PaymentService svc2 = new Reloader().rolloutRestart(cfg, sec);
        svc2.transfer(rajesh, priya, new BigDecimal("50000"));  // now fee 35
    }
}
