  name: payment-config-v7
  annotations: { reloader.stakater.com/match: "true" }  # Reloader watches changes
data:
  transfer.fee: "20"
  log.level: "INFO"
---
# k8s/secret.yaml — sensitive values, base64, encrypt etcd at rest, tight RBAC
apiVersion: v1
kind: Secret
metadata: { name: payment-secret }
type: Opaque
data:
  db.password: b2xkUGFzczEyMw==   # base64("oldPass123") — encoding, NOT encryption
